import {cloud} from './cloud.js';
import {categories,money,today,pennies,validDate,allocate,balance,forecast,weekSpent,validateTransaction,parseCSV,previewCSV,prepareCSVImport,splitBill,planReset,weekStart,weeklyDate,effectiveBudgets} from './core.js';

const paths={home:'M3 10 12 3l9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1Z',transactions:'M8 3H5v18h14V3h-3M9 3h6v4H9zM8 12h8M8 16h5',plan:'M5 5h14a2 2 0 0 1 2 2v13H3V7a2 2 0 0 1 2-2ZM7 3v4M17 3v4M3 10h18',allocation:'M3 7h18v13H3zM7 7V4h10v3M3 12h18M10 16h4',rehearsal:'m15 3 6 6-11 11H4v-6ZM13 5l6 6M4 20H2',shared:'M16 21v-3a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v3M9 10a4 4 0 1 0 0-8 4 4 0 0 0 0 8M22 21v-3a4 4 0 0 0-3-3.87M16 2.13a4 4 0 0 1 0 7.75',import:'M12 16V3m-5 5 5-5 5 5M3 14v7h18v-7',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8M4 4l2 2m12 12 2 2M4 20l2-2M18 6l2-2M12 1v3m0 16v3M1 12h3m16 0h3',arrow:'M4 12h16m-6-6 6 6-6 6',plus:'M12 5v14M5 12h14',check:'m5 12 4 4L19 6',shield:'M12 3 3 7v5c0 5 9 9 9 9s9-4 9-9V7ZM8 12l3 3 5-6',wallet:'M3 6h17v14H3zM3 6V3h14v3M16 12h5v4h-5z',leaf:'M20 3C5 2 2 9 6 17s16 2 14-14ZM5 21l10-12',groceries:'M3 5h2l3 12h10l3-8H6M9 21h.01M18 21h.01',transport:'M5 3h14v14H5zM5 11h14M8 17v4m8-4v4M8 7h.01M16 7h.01',food:'M5 3v7h5V3M7.5 10v11M18 3c-4 5-4 9 0 9V3v18',shopping:'M4 7h16l1 14H3ZM8 7V5a4 4 0 0 1 8 0v2',clock:'M12 8v5l3 2M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',edit:'m16 3 5 5-12 12H4v-5ZM14 5l5 5',trash:'M3 6h18M9 6V3h6v3M5 6l1 15h12l1-15M10 10v7m4-7v7',search:'M21 21l-6-6M17 10a7 7 0 1 1-14 0 7 7 0 0 1 14 0',more:'M5 12h.01M12 12h.01M19 12h.01',info:'M12 11v6m0-10h.01M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0'};
const icon=(name)=>`<svg viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name]||paths.wallet}"/></svg>`;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const uid=()=>crypto.randomUUID();
const dateLabel=(d,opts={day:'numeric',month:'short'})=>validDate(d)?new Date(d+'T12:00:00').toLocaleDateString('en-GB',opts):'Date missing';
const addDays=(date,days)=>{const d=new Date(date+'T12:00:00');d.setDate(d.getDate()+days);return d.toLocaleDateString('en-CA');};
const seed=()=>({version:1,name:'you',opening:132215,openingDate:today(),nextIncome:addDays(today(),42),buffer:0,updated:today(),forecastReviewed:today(),dirty:false,
  transactions:[{id:'t1',description:'Weekly food shop',amount:1875,date:today(),category:'Groceries',type:'expense'},{id:'t2',description:'Bus ticket',amount:420,date:today(),category:'Transport',type:'expense'},{id:'t3',description:'Coffee with a friend',amount:1220,date:addDays(today(),-1),category:'Eating out',type:'expense'}],
  budgets:{Groceries:6000,Transport:2500,'Eating out':3000,Shopping:2000,Entertainment:1500,Study:1000,Other:1000},
  events:[{id:'e1',name:'Part-time wages',type:'income',amount:24000,date:addDays(today(),5),estimated:true,paid:false},{id:'e2',name:'Rent',type:'bill',amount:39000,date:addDays(today(),14),estimated:false,paid:false},{id:'e3',name:'Travel pass',type:'bill',amount:4500,date:addDays(today(),16),estimated:false,paid:false}],
  allocation:{payment:120000,reserve:30000,weeks:6,amounts:allocate(90000,6)},
  shared:[{id:'s1',name:'November rent',amount:105000,date:addDays(today(),14),people:['You','Alex','Sam'],shares:[35000,35000,35000],settled:[],method:'equal'},{id:'s2',name:'Electricity',amount:8400,date:addDays(today(),18),people:['You','Alex','Sam'],shares:[2800,2800,2800],settled:[],method:'equal'}]});
const GUEST_KEY='termwise-mvp-v1';let KEY=GUEST_KEY;let accountLoading=cloud.configured,authMode='signin',accountIssue='';let state;let storageError=false;
try{const saved=JSON.parse(localStorage.getItem(KEY));state=saved?.version===1&&Array.isArray(saved.transactions)?saved:seed();}catch{state=seed();storageError=true;}
let route='', csv=null, csvMapping=null, csvPreview=null, csvName='', csvImported=0, rehearsal=null, resetPreview=null, toastTimer;
function persist(next,message){
 let oldPending,oldBase,metadata=false;
 try{
  if(accountLoading)throw new Error('Account is loading');const serialized=JSON.stringify(next);
  if(cloud.user){oldPending=localStorage.getItem(KEY+'-pending');oldBase=localStorage.getItem(KEY+'-base');metadata=true;localStorage.setItem(KEY+'-pending','true');if(oldBase===null)localStorage.setItem(KEY+'-base',String(cloud.revision));}
  localStorage.setItem(KEY,serialized);state=next;if(cloud.user)cloud.queue(next);if(message)toast(message);return true;
 }catch{
  if(metadata){try{localStorage.removeItem(KEY+'-pending');localStorage.removeItem(KEY+'-base');if(oldPending!==null)localStorage.setItem(KEY+'-pending',oldPending);if(oldBase!==null)localStorage.setItem(KEY+'-base',oldBase);}catch{}}
  toast('Could not save: device storage is unavailable or full. Your previous data is unchanged.');return false;
 }
}
function change(fn,message,dirty=true){const next=structuredClone(state);fn(next);next.updated=today();if(dirty)next.dirty=true;return persist(next,message);}
function toast(message){const t=document.querySelector('#toast');t.textContent=message;t.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('visible'),4500);}
const button=(label,action,kind='',ico='arrow')=>`<button ${/\btype=/.test(action)?'':'type="button"'} aria-label="${esc(label.replace(/<[^>]+>/g,''))}" class="button ${kind}" ${action}>${label}${icon(ico)}</button>`;
const field=(label,name,value,type='text',extra='')=>`<label class="field"><span>${label}</span><input name="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`;
const catOptions=(value,blank=false)=>`${blank?'<option value="">Choose a category</option>':''}${categories.map(c=>`<option ${c===value?'selected':''}>${c}</option>`).join('')}`;
const heading=(title,sub,action='',eyebrow='A LITTLE PLANNING GOES A LONG WAY')=>`<div class="heading"><div><p class="eyebrow">${eyebrow}</p><h1>${title}</h1><p class="subtitle">${sub}</p></div>${action}</div>`;
const panel=(title,body,action='',sub='')=>`<section class="panel"><div class="panel-head"><div><h2>${title}</h2>${sub?`<p>${sub}</p>`:''}</div>${action}</div>${body}</section>`;
const note=(title,text='',kind='',ico='info')=>`<div class="note ${kind}">${icon(ico)}<div><strong>${title}</strong>${text?`<small>${text}</small>`:''}</div></div>`;
const status=(text,kind='')=>`<span class="status ${kind}">${esc(text)}</span>`;
const textButton=(label,action,ico='arrow')=>`<button type="button" ${!label?'aria-label="Edit item"':''} class="text-button" ${action}>${label}${icon(ico)}</button>`;
const empty=text=>`<div class="empty">${text}</div>`;
const routes=[['home','Overview','home'],['transactions','Transactions','transactions'],['plan','Term runway','plan'],['allocation','Income smoother','allocation'],['rehearsal','Purchase rehearsal','rehearsal'],['shared','Shared bills','shared'],['import','CSV import','import'],['reset','Reset Week','clock'],['account','Account & sync','shield'],['support','Support snapshots','shared']];
function renderNav(){document.querySelector('#navigation').innerHTML=routes.map(([id,label,ico])=>`<button class="nav-link ${route===id?'active':''}" data-route="${id}" ${route===id?'aria-current="page"':''}>${icon(ico)}${label}</button>`).join('')+`<div style="height:16px"></div><button class="nav-link ${route==='settings'?'active':''}" data-route="settings">${icon('settings')}Settings & data</button>`;
 const mobile=[['home','Home','home'],['plan','Plan','plan'],['transactions','Activity','transactions'],['shared','Shared','shared'],['more','More','more']];
 document.querySelector('#mobile-navigation').innerHTML=mobile.map(([id,label,ico])=>`<button data-${id==='more'?'action="more"':`route="${id}"`} class="${route===id||(id==='more'&&['settings','import','allocation','rehearsal','reset','account','support'].includes(route))?'active':''}">${icon(ico)}${label}</button>`).join('');
 document.querySelector('#breadcrumb').innerHTML=`<span class="crumb">Your workspace</span> <span>/</span> <span class="crumb">${routes.find(r=>r[0]===route)?.[1]||'Settings & data'}</span>`;
 if(innerWidth<=650)document.querySelector('#breadcrumb').textContent='termwise.';
}
function forecastHero(){const f=forecast(state),stale=state.dirty||state.forecastReviewed!==today();return `<section class="hero"><div class="hero-decoration"></div><p class="eyebrow">WEEKLY FLEXIBLE ESTIMATE</p><div class="amount">${f.complete?(f.shortfall?money(f.shortfall):money(f.weekly)):'—'} <small>${f.shortfall?'shortfall':f.complete?'/ week':''}</small></div><p>${!f.complete?'Complete your dates to see a reliable weekly estimate.':f.shortfall?'Your protected costs exceed your confirmed money.':'A little room for everything that makes this week yours.'}</p><span class="status ${stale?'amber':''}">${icon(stale?'clock':'check')}${!f.complete?'Forecast incomplete':stale?'Out of date · review inputs':'Updated today · based on your records'}</span><div class="hero-footer"><span>${f.complete?`${f.weeks} weeks until your next payment`:'Next payment date needed'}</span><a href="#plan">View your runway ${icon('arrow')}</a></div></section>`;}
function eventHTML(e,editable=false){const overdue=e.date<today()&&!e.paid;const label=e.paid?(e.type==='income'?'Received':'Paid'):e.date===today()?'Due today':overdue?'Overdue':e.type==='income'?'Expected':e.estimated?'Estimated bill':'Reserved';return `<div class="event"><div class="date-tile">${validDate(e.date)?dateLabel(e.date,{month:'short'}):'—'}<strong>${validDate(e.date)?dateLabel(e.date,{day:'numeric'}):'?'}</strong></div><div class="event-info"><strong>${esc(e.name)}</strong><small>${e.type==='income'?'Expected income · excluded until received':`Essential bill${e.estimated?' · estimated amount':''}`}</small></div><div class="event-right">${e.type==='income'?'+':'−'}${money(e.amount)}<br>${status(label,overdue||e.estimated?'amber':'')}</div>${editable?textButton('','data-edit-event="'+esc(e.id)+'"','edit'):''}</div>`;}
function transactionsHTML(items,edit=false){return items.length?items.map(t=>`<div class="transaction"><div class="category-icon">${icon(t.category==='Groceries'?'groceries':t.category==='Transport'?'transport':t.category==='Eating out'?'food':'shopping')}</div><div><strong>${esc(t.description||t.category)}</strong><small>${esc(t.category)} · ${dateLabel(t.date)}</small></div><span class="price ${t.type==='income'?'income':''}">${t.type==='income'?'+':'−'}${money(t.amount)}</span>${edit?textButton('Edit',`data-edit-transaction="${t.id}"`,'edit'):''}</div>`).join(''):empty('No transactions yet. Add your first expense to start your plan.');}
function budgetHTML(c){const used=weekSpent(state,c),limit=effectiveBudgets(state)[c]||0;return `<div class="budget-row"><div class="budget-title"><span>${esc(c)}</span><span><b>${money(used)}</b> / ${money(limit)}</span></div><div class="progress"><span class="${used>=limit?'warning':''}" style="width:${Math.min(100,limit?used/limit*100:100)}%"></span></div><small>${used>limit?`${money(used-limit)} over your limit`:used===limit?'Limit reached · £0.00 remaining':`${money(limit-used)} left this week`}</small></div>`;}
function home(){const f=forecast(state);return heading(`Your term, in view<span style="color:#a7b47e">.</span>`,'A clearer picture of your money. A little more peace of mind.',button('<span class="button-label">Add transaction</span>','data-action="add-transaction"','','plus'))+`<div class="grid-main home-grid"><div class="stack">${forecastHero()}<div class="summary-grid"><div class="summary"><div class="summary-label">${icon('wallet')}Current balance</div><strong>${money(f.confirmed)}</strong><small>Confirmed money only</small></div><div class="summary"><div class="summary-label">${icon('shield')}Protected essentials</div><strong>${money(f.essentials)}</strong><small>Set aside for your bills</small></div><div class="summary"><div class="summary-label">${icon('groceries')}Spent this week</div><strong>${money(weekSpent(state))}</strong><small>Monday to today</small></div></div>${panel('Your weekly budgets',categories.slice(0,3).map(budgetHTML).join(''),textButton('Manage','data-action="budgets"'),'A bit of structure, with room for real life.')}${panel('Recent transactions',transactionsHTML([...state.transactions].sort((a,b)=>b.date.localeCompare(a.date)).slice(0,4)),textButton('View all','data-route="transactions"'))}</div><div class="stack">${panel('Coming up',state.events.filter(e=>!e.paid).sort((a,b)=>a.date.localeCompare(b.date)).slice(0,3).map(e=>eventHTML(e)).join('')+`<div class="spacer"></div>${note('Essentials come first.','Reserved bills are kept separate from your flexible money.','','shield')}`,textButton('View all','data-route="plan"'))}<section class="quick-card">${icon('rehearsal')}<h2>Something on your mind?<br>Try it before you buy it.</h2><p>See what a purchase could mean for your week, before making the call.</p>${textButton('Rehearse a purchase','data-route="rehearsal"')}</section>${note('Your plan, at your pace.','You can correct a record or adjust your limits whenever life changes.','','leaf')}</div></div>`;}
function transactions(){return heading('The little things add up.','Every entry brings your plan a little closer to real life.',button('Add transaction','data-action="add-transaction"','','plus'),'YOUR TRANSACTIONS')+`<div class="grid-main"><div class="stack">${panel('Your activity',`<div class="toolbar"><input class="search-input" id="transaction-search" placeholder="Search transactions…" aria-label="Search transactions"><select id="transaction-filter" aria-label="Filter by category"><option value="">All categories</option>${catOptions('')}</select></div><div id="transaction-list">${transactionTable(state.transactions)}</div>`,textButton('Export CSV','data-action="export"','import'))}</div><div class="stack">${panel('Weekly category budgets',categories.map(budgetHTML).join(''),textButton('Edit','data-action="budgets"','edit'))}${note('This is your private spending.','Personal entries do not appear in the household ledger.','','shield')}</div></div>`;}
function transactionTable(items){return items.length?`<div class="table-wrap"><table><thead><tr><th>Transaction</th><th>Category</th><th>Amount</th><th><span class="muted">Actions</span></th></tr></thead><tbody>${[...items].sort((a,b)=>b.date.localeCompare(a.date)).map(t=>`<tr><td>${esc(t.description||t.category)}<small>${dateLabel(t.date,{day:'numeric',month:'short',year:'numeric'})}</small></td><td>${esc(t.category)}</td><td class="amount-cell ${t.type==='income'?'income':''}">${t.type==='income'?'+':'−'}${money(t.amount)}</td><td>${textButton('Edit',`data-edit-transaction="${t.id}"`,'edit')}</td></tr>`).join('')}</tbody></table></div>`:empty('No transactions match. Try another search or add a new entry.');}
function plan(){const f=forecast(state);return heading('Your money has a timeline.','Keep the next payment and the bills in between in one view.',button('Add a bill or income','data-action="add-event"','','plus'),'TERM RUNWAY')+`<div class="grid-main"><div class="stack">${forecastHero()}${panel('Coming up',state.events.length?[...state.events].sort((a,b)=>a.date.localeCompare(b.date)).map(e=>eventHTML(e,true)).join(''):empty('Add your essential bills and expected income.'),status('DATED & CLEAR'))}${note('An estimate from your records, not a guarantee.','Expected income is shown on the timeline but is not available money until you mark it received.','','info')}</div><div class="stack">${panel('Forecast inputs',`<form id="forecast-form"><div class="error" hidden></div>${field('Opening balance (£)','opening',(state.opening/100).toFixed(2),'number','min="0" step="0.01" required')}${field('Opening balance date','openingDate',state.openingDate,'date','required')}${field('Next payment date','nextIncome',state.nextIncome,'date')}${field('Emergency buffer (£)','buffer',(state.buffer/100).toFixed(2),'number','min="0" step="0.01" required')}<div class="coverage-row"><span>Confirmed balance</span><strong>${money(f.confirmed)}</strong></div><div class="coverage-row"><span>Unpaid essentials</span><strong>−${money(f.essentials)}</strong></div><div class="coverage-row"><span>Emergency buffer</span><strong>−${money(state.buffer)}</strong></div><div class="coverage-row"><span>Flexible money</span><strong>${money(f.flexible)}</strong></div><div class="spacer"></div>${button('Save & refresh forecast','type="submit"','full','check')}<p class="form-note">Calculated using the actual days until your next payment.</p></form>`)}${note('Something missing?','A missing payment or bill date makes the forecast incomplete. Review your figures whenever a bill changes.','amber','clock')}</div></div>`;}
function allocation(){const a=state.allocation;return heading('Make income last.','Give every week a realistic starting point.','', 'INCOME SMOOTHER')+`<div class="grid-main"><section class="panel form-card"><form id="allocation-form"><div class="error" hidden></div><div id="allocation-preview"></div><div class="spacer"></div>${field('Payment to plan (£)','payment',(a.payment/100).toFixed(2),'number','step="0.01" min="0" required')}${field('Protect essentials first (£)','reserve',(a.reserve/100).toFixed(2),'number','step="0.01" min="0" required')}${field('Weeks to cover','weeks',a.weeks,'number','min="1" max="104" step="1" required')}<div id="allocation-calculation" class="small-copy"></div><div class="spacer"></div>${button('Save weekly allocation','type="submit"','full')}<p class="form-note">This plan allocates a payment. It does not add income to your balance.</p></form></section><div class="stack">${panel('Your weekly envelopes',`<div id="envelopes"></div>`,status('PREVIEW'))}<div class="guide">${icon('leaf')}<h2>Protect first. Then spread.</h2><p>Set aside essential costs before dividing the flexible remainder. Whole pennies stay accounted for, even when the numbers do not divide evenly.</p><ul><li>Your essential reserve stays intact.</li><li>Extra pennies go to the first weeks.</li><li>Saving a plan never changes past transactions.</li></ul></div></div></div>`;}
function allocationPreview(){const form=document.querySelector('#allocation-form');try{const p=pennies(form.payment.value),r=pennies(form.reserve.value),weeks=Number(form.weeks.value),savedMatches=p===state.allocation.payment&&r===state.allocation.reserve&&weeks===state.allocation.weeks,amounts=savedMatches?state.allocation.amounts:allocate(p-r,weeks);document.querySelector('#allocation-preview').innerHTML=`<div class="hero"><p class="eyebrow">${p<r?'ESSENTIAL SHORTFALL':'WEEKLY ALLOCATION'}</p><div class="amount">${money(p<r?r-p:amounts[0]||0)}</div><p>${p<r?'Essentials exceed this payment. Reduce the plan or revise your inputs; reserves stay intact.':`${money(amounts.reduce((sum,n)=>sum+n,0))} flexible money spread across ${weeks} weeks`}</p></div>`;document.querySelector('#allocation-calculation').textContent=`${money(p)} − ${money(r)} = ${money(p-r)} available to allocate`;document.querySelector('#envelopes').innerHTML=amounts.length?`<div class="week-grid">${amounts.map((n,i)=>`<div class="week-card"><span>Week ${i+1}${savedMatches?` · ${dateLabel(weeklyDate(state.allocation.startDate||weekStart(),i))}`:''}</span><strong>${money(n)}</strong></div>`).join('')}</div><div class="spacer"></div>${note('Every penny has a place.',`Total allocated: ${money(amounts.reduce((s,x)=>s+x,0))}`,'','check')}`:note('No flexible allocation.','Essential reserves exceed the payment.','amber');}catch{document.querySelector('#allocation-preview').innerHTML=note('Complete the fields below.','Use valid amounts and 1–104 whole weeks.','amber');document.querySelector('#envelopes').innerHTML='';}}
function rehearsalPage(){return heading('Try before you spend.','See the effect before making a decision.','', 'PURCHASE REHEARSAL')+`<div class="grid-main"><section class="panel form-card"><div class="panel-head"><h2>What are you thinking about?</h2>${status('PREVIEW ONLY')}</div><form id="rehearsal-form"><div class="error" hidden></div>${field('Purchase name (optional)','name',rehearsal?.name||'','text','placeholder="e.g. A new travel pass" maxlength="120"')}${field('Purchase amount (£)','amount',rehearsal?.value||'32.00','number','step="0.01" min="0.01" required')}${button('Preview this purchase','type="submit"','full')}</form><div id="rehearsal-result"></div></section><div class="stack">${panel('A decision with the full picture.',note('Nothing is spent in a preview.','Your balance and transactions stay exactly as they are.','','shield')+'<div class="spacer"></div><p class="small-copy">The comparison shows the impact on this week’s flexible amount. You can also check your confirmed money against every upcoming essential bill.</p>')}<div class="quick-card">${icon('leaf')}<h2>It’s your call.</h2><p>A preview gives you the numbers. You decide what matters for your week.</p></div></div></div>`;}
function showRehearsal(){const f=forecast(state),el=document.querySelector('#rehearsal-result');if(!rehearsal){el.innerHTML='';return;}if(!f.complete||state.dirty||state.forecastReviewed!==today()){el.innerHTML=`<div class="spacer"></div>${note('Refresh your forecast first.','The estimate is incomplete or out of date. Review the dates and amounts before previewing a purchase.','amber')}${button('Review forecast inputs','data-route="plan"','full secondary')}`;return;}const after=(f.shortfall?-f.shortfall:f.weekly)-rehearsal.amount;el.innerHTML=`<div class="hero" style="margin-top:24px"><p class="eyebrow">THIS WEEK · ${esc(rehearsal.name||'YOUR PURCHASE')}</p><div class="comparison"><div><div class="amount">${money(f.weekly)}</div><small>Current estimate</small></div><span>→</span><div><div class="amount">${money(after)}</div><small>After purchase</small></div></div><div class="hero-footer">Your protected bills stay reserved.</div></div><div class="spacer"></div>${note(after<0?`${money(-after)} weekly shortfall`:'Room in your plan',after<0?'This purchase goes beyond this week’s flexible amount.':`This preview leaves ${money(after)} for flexible spending. No transaction has been recorded.`,after<0?'amber':'') }<div class="spacer"></div>${button('Review essential coverage','data-action="coverage"','full') }<div class="spacer"></div>${button('Discard preview','data-action="discard-preview"','full secondary')}`;}
function shared(){if(cloud.user)return onlineShared();const total=state.shared.reduce((s,b)=>{const i=b.people.indexOf('You');return s+(i>=0&&!b.settled.includes('You')?b.shares[i]:0);},0);return heading('A shared home. A clearer ledger.','Household bills together. Personal spending stays yours.',button('Record a shared bill','data-action="add-shared"','','plus'),'PRIVATE HOUSEMATE LEDGER')+`<div class="grid-main"><div class="stack">${state.shared.length?state.shared.map(b=>`<article class="bill-card" style="background:white"><div class="bill-top"><div><h3>${esc(b.name)}</h3><p>${money(b.amount)} total · ${esc(b.method)} split · ${dateLabel(b.date)}</p></div><div><strong>${money(b.shares[b.people.indexOf('You')]||0)}</strong><p>Your share</p></div></div><div class="bill-shares">${b.people.map((p,i)=>`<div>${esc(p)}<strong>${money(b.shares[i])}</strong><span class="status ${b.settled.includes(p)?'':'amber'}" style="margin-top:7px">${b.settled.includes(p)?'Settled':'Outstanding'}</span></div>`).join('')}</div><div class="bill-actions"><span class="small-copy">${b.people.length} participants · household bill</span>${textButton('Manage',`data-manage-shared="${b.id}"`,'edit')}</div></article>`).join(''):empty('No shared bills yet. Record a household cost to get started.')}</div><div class="stack"><div class="hero"><p class="eyebrow">YOUR OUTSTANDING SHARE</p><div class="amount">${money(total)}</div><p>Across ${state.shared.length} household bills</p></div>${note('Only shared items appear here.','Your personal transaction log is separate from this household ledger.','lime','shared')}${panel('Local household ledger','<p class="small-copy">Record costs and mark shares settled on this device. This MVP does not send bills, invite housemates, or give other people access. Real shared accounts need a secure backend.</p>')}</div></div>`;}
function importPage(){return heading('Bring your records with you.','Review your CSV without changing a single saved entry.','', 'MANUAL & CSV FLOW')+`<div class="grid-main"><section class="panel"><div class="steps"><div class="step ${!csv?'active':''}">1 &nbsp; CHOOSE FILE</div><div class="step ${csv&&!csvPreview?'active':''}">2 &nbsp; MAP COLUMNS</div><div class="step ${csvPreview?'active':''}">3 &nbsp; REVIEW</div></div><div id="csv-content">${csvPreview?csvReviewHTML():csv?csvMapHTML():`<label class="upload">${icon('import')}<strong>A fresh start, without retyping.</strong><small>Choose a UTF-8 CSV with date, description, amount and category columns.<br>GBP expenses · YYYY-MM-DD dates · up to 5,000 rows</small><input type="file" id="csv-file" accept=".csv,text/csv" aria-label="Choose a CSV file"></label><div class="spacer"></div><p class="small-copy">Need an example? <a href="/sample-transactions.csv" download>Download a sample CSV</a>.</p>`}</div></section><div class="stack">${panel('Review first. Always.',note('Your data stays untouched.','Choosing a file, mapping columns and viewing rows never adds transactions.','','shield')+'<div class="spacer"></div><p class="small-copy">Review every row before confirming. Only ready rows will be added. Duplicates and invalid rows remain excluded, and nothing is saved until you confirm the import.</p>')}<div class="guide"><h2>A few things to know.</h2><ul><li>Amounts are positive expense values.</li><li>Use the categories in your budget.</li><li>Quotes and commas in notes are supported.</li><li>Currency, if provided, must be GBP.</li></ul></div></div></div>`;}
function csvMapHTML(){return `<div class="file-name">${icon('transactions')} ${esc(csvName)}</div><p class="small-copy">${csv.rows.length} rows found. Choose the matching column for each field.</p><div class="spacer"></div><form id="csv-map-form"><div class="error" hidden></div><div class="mapping">${['date','description','amount','category'].map((k,i)=>`<label class="field"><span>${k}</span><select name="${k}" required><option value="">Select a column</option>${csv.headers.map((h,index)=>`<option value="${index}" ${csvMapping?.[k]===index||(!csvMapping&&h===k)?'selected':''}>${esc(h)}</option>`).join('')}</select></label>`).join('')}</div>${button('Preview rows','type="submit"','full')}<div class="spacer"></div>${textButton('Choose another file','data-action="clear-csv"')}</form>`;}
function csvReviewHTML(){const ready=csvPreview.filter(r=>r.status==='Ready').length,duplicates=csvPreview.filter(r=>r.status==='Duplicate').length,errors=csvPreview.length-ready-duplicates;return `<p class="file-name">${esc(csvName)}</p><p class="small-copy">${csvPreview.length} rows · GBP · expense records</p><div class="stats-row"><div class="stat-box"><strong>${ready}</strong><span>Ready in this preview</span></div><div class="stat-box amber"><strong>${duplicates+errors}</strong><span>${duplicates} duplicates · ${errors} errors</span></div></div><div class="table-wrap"><table><thead><tr><th>Transaction</th><th>Amount</th><th>Status</th></tr></thead><tbody>${csvPreview.slice(0,200).map(r=>`<tr><td>${esc(r.description||'No description')}<small>${esc(r.date)} · ${esc(r.category)}</small></td><td class="amount-cell">${Number.isFinite(r.amount)?'−'+money(r.amount):'—'}</td><td>${status(r.status,r.status==='Ready'?'':'amber')}${r.error?`<small>${esc(r.error)}</small>`:''}</td></tr>`).join('')}</tbody></table></div>${csvPreview.length>200?'<p class="small-copy">Showing the first 200 rows. All rows were validated.</p>':''}<div class="spacer"></div>${note(csvImported?`${csvImported} transactions imported.`:'Ready for your review.',csvImported?'Your saved balance and budgets have been updated. Imported rows now appear as duplicates.':`${ready} ready rows can be imported. ${duplicates} duplicates and ${errors} errors will be excluded.`,'','check')}<div class="spacer"></div>${button(`Import ${ready} transaction${ready===1?'':'s'}`,`data-action="confirm-csv" ${ready===0?'disabled':''}`,'full','check')}<div class="actions">${button('Back to mapping','data-action="back-mapping"','secondary','edit')}${textButton('Choose another file','data-action="clear-csv"')}</div>`;}

function resetPage(){
 const overspend=categories.reduce((sum,c)=>sum+Math.max(0,weekSpent(state,c)-(effectiveBudgets(state)[c]||0)),0);
 return heading('A fresh plan for the weeks ahead.','Recover at your own pace. Your essential bills stay protected.','','RESET WEEK')+
 '<div class="grid-main"><section class="panel"><form id="reset-form"><div class="error" role="alert" hidden></div>'+field('Amount to recover (£)','amount',(overspend/100).toFixed(2),'number','step="0.01" min="0.01" required')+
 '<p class="small-copy">Current category overspend: '+money(overspend)+'. You can enter a different recovery amount.</p><div class="spacer"></div><span class="field-label">Choose flexible categories to adjust</span>'+categories.map(c=>'<label class="check"><input type="checkbox" name="category" value="'+esc(c)+'" checked>'+esc(c)+' · '+money(state.budgets[c]||0)+' weekly limit</label>').join('')+
 button('Preview recovery plan','type="submit"','full')+'<p class="form-note">Only future weekly allocations and your selected flexible categories can change.</p></form><div id="reset-result">'+resetResultHTML()+'</div></section><div class="stack">'+
 panel('Protected essentials',state.events.filter(e=>e.type==='bill'&&!e.paid).map(e=>eventHTML(e)).join('')+note('Your essentials stay intact.','A reset never reduces bills, removes protection, or changes recorded transactions.','','shield'))+
 (state.resetUndo?panel('You can step back.',note('Your last reset can be undone.','Restores its future allocation and category limits while keeping later transactions.')+'<div class="spacer"></div>'+button('Undo last reset','data-action="undo-reset"','full secondary','clock')):'')+
 panel('How recovery works.','<p class="small-copy">Your current and past weeks remain unchanged. The recovery amount is spread across future weeks within the capacity of the categories you select. Review the exact cuts before confirming. Saving a new income allocation replaces the future plan and clears reset undo.</p>')+'</div></div>';
}
function resetResultHTML(){
 if(!resetPreview)return '';
 return '<div class="spacer"></div><h2>Review the changes</h2><div class="spacer"></div><div class="table-wrap"><table><thead><tr><th>Future week</th><th>Before</th><th>After</th></tr></thead><tbody>'+resetPreview.rows.map(r=>'<tr><td>'+dateLabel(r.date)+'<small>'+Object.entries(r.cuts).map(([c,n])=>esc(c)+': −'+money(n)).join(' · ')+'</small></td><td>'+money(r.value)+'</td><td>'+money(r.after)+'</td></tr>').join('')+'</tbody></table></div><div class="spacer"></div>'+note('Total recovery: '+money(resetPreview.amount),'Past spending, current-week limits and essential bills stay unchanged.','lime','check')+'<div class="actions">'+button('Discard proposal','data-action="discard-reset"','secondary')+button('Confirm reset','data-action="apply-reset"','','check')+'</div>';
}

function settings(){return heading('Your plan. Your settings.','A few details to make this space your own.','', 'SETTINGS & DATA')+`<div class="grid-main"><div class="stack">${panel('Your details',`<form id="settings-form"><div class="error" hidden></div>${field('Your name','name',state.name==='you'?'':state.name,'text','maxlength="60" placeholder="What should we call you?"')}${button('Save details','type="submit"','','check')}</form>`)}${panel('Your data, in your hands.',`<p class="small-copy">${cloud.user?'Your account plan is stored locally and synced to Supabase. Check the sync status before switching devices. Clearing this plan also updates the cloud copy; existing shared snapshots remain dated copies until revoked.':'Your guest plan stays in this browser. Sign in through Account & sync to use a separate cloud plan. Export a copy before clearing browser data.'}</p><div class="actions">${button('Export transactions','data-action="export"','secondary','import')}${button('Delete all local data','data-action="delete-data"','danger','trash')}</div>`)}${panel('Start with a blank plan',`<p class="small-copy">The first visit includes sample records to help you explore. Clear the sample data to enter your own opening balance, dates and expenses.</p><div class="spacer"></div>${button('Start my own plan','data-action="start-blank"','secondary','plus')}`)}</div><div class="stack">${note('Your budgeting toolkit','Transactions, budgets, forecasts, allocations, purchase previews, confirmed CSV imports and recovery plans.','lime','check')}${panel('Accounts and online sharing','<p class="small-copy">Confirmed import and Reset Week are available. Open Account & sync to enable cloud saving, household collaboration and support snapshots after Supabase is configured.</p>')}${note('Built around manual entry.','Check your balance and dates regularly to keep your forecast useful.','','leaf')}</div></div>`;}
function render(){route=location.hash.slice(1)||'home';if(route.startsWith('invite=')){sessionStorage.setItem('termwise-invite',route.slice(7));route='account';}if(route.startsWith('snapshot=')){sessionStorage.setItem('termwise-snapshot',route.slice(9));route=cloud.user?'support':'account';}if(![...routes.map(r=>r[0]),'settings'].includes(route))route='home';renderNav();if(accountLoading){document.querySelector('#main').innerHTML=heading('Opening your account…','Loading your private cloud plan.');return;}document.querySelector('#main').innerHTML=({home,transactions,plan,allocation,rehearsal:rehearsalPage,shared,import:importPage,reset:resetPage,account:accountPage,support:supportPage,settings}[route])();document.title=`Termwise — ${routes.find(r=>r[0]===route)?.[1]||'Settings'}`;if(route==='allocation')allocationPreview();if(route==='rehearsal')showRehearsal();updateSyncStatus();if(route==='shared'&&cloud.user&&!householdLoaded&&!householdLoading)refreshHouseholds();if(route==='support'&&cloud.user&&!snapshotsLoaded&&!snapshotsLoading)refreshSnapshots();}
function modal(title,body){document.querySelector('#dialog-content').innerHTML=`<div class="dialog-head"><h2>${title}</h2><button class="close" data-action="close-dialog" aria-label="Close dialog">×</button></div>${body}`;document.querySelector('#dialog').showModal();}
function closeModal(){document.querySelector('#dialog').close();}
function transactionModal(id){const t=state.transactions.find(t=>t.id===id);modal(t?'Edit transaction':'Add a transaction',`<form id="transaction-form" data-id="${t?.id||''}"><div class="error" role="alert" hidden></div><div class="tabs"><button type="button" data-type="expense" class="${!t||t.type==='expense'?'active':''}">Expense</button><button type="button" data-type="income" class="${t?.type==='income'?'active':''}">Income received</button></div><input type="hidden" name="type" value="${t?.type||'expense'}"><label class="field big"><span>Amount in GBP</span><div class="amount-input">£<input aria-label="Amount in pounds" name="amount" type="number" min="0.01" step="0.01" required placeholder="0.00" value="${t?(t.amount/100).toFixed(2):''}"></div></label><label class="field"><span>Category</span><select name="category" required>${catOptions(t?.category,true)}</select></label>${field('Date','date',t?.date||today(),'date','required')}${field('Note · optional','description',t?.description||'','text','maxlength="180" placeholder="e.g. Weekly food shop"')}<div class="after-card"><div><span>After saving</span><strong id="transaction-after">—</strong></div><span>confirmed balance</span></div>${button('Save transaction','type="submit"','full','check')}<p class="form-note">Your balance changes only when you save.</p>${t?`<div class="spacer"></div>${textButton('Delete this transaction',`data-delete-transaction="${t.id}"`,'trash')}`:''}</form>`);transactionAfter();}
function transactionAfter(){const form=document.querySelector('#transaction-form');if(!form)return;try{const old=state.transactions.find(t=>t.id===form.dataset.id),oldEffect=old?(old.type==='income'?old.amount:-old.amount):0,amount=pennies(form.amount.value||'0');document.querySelector('#transaction-after').textContent=money(balance(state)-oldEffect+(form.type.value==='income'?amount:-amount));}catch{document.querySelector('#transaction-after').textContent='—';}}
function eventModal(id){const e=state.events.find(e=>e.id===id);modal(e?'Edit timeline item':'Add a bill or income',`<form id="event-form" data-id="${e?.id||''}"><div class="error" role="alert" hidden></div><label class="field"><span>Item type</span><select name="type"><option value="bill">Essential bill</option><option value="income" ${e?.type==='income'?'selected':''}>Expected income</option></select></label>${field('Name','name',e?.name||'','text','required maxlength="100"')}${field('Amount (£)','amount',e?(e.amount/100).toFixed(2):'','number','min="0.01" step="0.01" required')}${field('Due or expected date','date',e?.date||'','date')}<label class="check"><input name="estimated" type="checkbox" ${e?.estimated?'checked':''}>This amount is estimated</label>${button('Save timeline item','type="submit"','full','check')}<p class="form-note">Bills stay reserved until paid. Income stays excluded until received.</p>${e?`<div class="actions">${e.paid?status(e.type==='income'?'Received':'Paid'):button(e.type==='income'?'Mark received':'Mark paid',`type="button" data-pay-event="${e.id}"`,'secondary','check')}${textButton('Delete',`data-delete-event="${e.id}"`,'trash')}</div>`:''}</form>`);}
function budgetsModal(){modal('Your weekly limits',`<form id="budgets-form"><div class="error" role="alert" hidden></div><p class="dialog-copy">Set a cap for each flexible category. Limits run from Monday to Sunday.</p><div class="form-grid keep-two">${categories.map(c=>field(c+' (£)',c,(effectiveBudgets(state)[c]/100).toFixed(2),'number','step="0.01" min="0.01" max="10000" required')).join('')}</div>${button('Save weekly limits','type="submit"','full','check')}</form>`);}
function sharedModal(){modal('Record a shared bill',`<form id="shared-form"><div class="error" role="alert" hidden></div>${field('Bill name','name','','text','required maxlength="100"')}${field('Total amount (£)','amount','','number','min="0.01" step="0.01" required')}${field('Due date','date',today(),'date','required')}<span class="field-label">Participants</span>${['You','Alex','Sam'].map(p=>`<label class="check"><input type="checkbox" name="people" value="${p}" checked>${p}</label>`).join('')}<label class="field"><span>Split method</span><select name="method"><option value="equal">Equal shares</option><option value="percentage">Percentage shares</option><option value="custom">Custom amounts</option></select></label><div id="share-inputs"></div>${button('Save shared bill','type="submit"','full','check')}<p class="form-note">A household record only. No personal transaction is created.</p></form>`);}
function shareInputs(){const f=document.querySelector('#shared-form'),people=[...f.querySelectorAll('[name="people"]:checked')].map(e=>e.value);document.querySelector('#share-inputs').innerHTML=f.method.value==='equal'?note('Split equally.',`Every selected participant receives a reconciled share.`):people.map(p=>field(p+(f.method.value==='percentage'?' (%)':' (£)'),'share-'+p,'','number','min="0" step="0.01" required')).join('');}
function coverage(){const f=forecast(state);let available=f.confirmed-(rehearsal?.amount||0);const bills=state.events.filter(e=>e.type==='bill'&&!e.paid&&e.date<=state.nextIncome).sort((a,b)=>a.date.localeCompare(b.date));modal('Essential coverage',`<p class="dialog-copy">After the proposed ${money(rehearsal?.amount||0)} purchase, confirmed money would be ${money(available)}. Expected income is excluded.</p>${bills.map(b=>{available-=b.amount;return `<div class="coverage-row"><div>${esc(b.name)}<small class="small-copy" style="display:block">${dateLabel(b.date)} · ${money(b.amount)}</small></div>${status(available>=0?'Covered':`${money(-available)} shortfall`,available>=0?'':'amber')}</div>`;}).join('')||empty('No unpaid essential bills in this period.')}<div class="spacer"></div>${note(available-state.buffer>=0?'Essentials and buffer remain covered.':`${money(Math.abs(available-state.buffer))} missing after essentials and buffer`, 'This is a preview. Your saved records have not changed.',available-state.buffer<0?'amber':'')}<div class="spacer"></div>${button('Back to preview','data-action="close-dialog"','full secondary')}`);}
function exportCSV(){const quote=x=>'"'+String(x).replaceAll('"','""')+'"';const rows=[['date','description','amount','category','type','currency'],...state.transactions.map(t=>[t.date,t.description,(t.amount/100).toFixed(2),t.category,t.type,'GBP'])];const blob=new Blob(['\uFEFF'+rows.map(r=>r.map(quote).join(',')).join('\r\n')],{type:'text/csv;charset=utf-8'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`termwise-transactions-${today()}.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Your transaction export is ready.');}
function confirmAction(title,copy,action,label){modal(title,`<p class="dialog-copy">${copy}</p><div class="actions">${button('Cancel','data-action="close-dialog"','secondary','arrow')}${button(label,`data-action="${action}"`,'danger','trash')}</div>`);}
const error=(form,e)=>{const el=form.querySelector('.error');el.textContent=e.message;el.hidden=false;el.scrollIntoView({block:'nearest'});};
document.addEventListener('submit',e=>{e.preventDefault();const f=e.target;if(!(f instanceof HTMLFormElement))return;try{
  if(f.id==='transaction-form'){if(f.dataset.saved==='true')return;const t={id:f.dataset.id||uid(),type:f.type.value,amount:pennies(f.amount.value),date:f.date.value,category:f.category.value,description:f.description.value.trim()};validateTransaction(t);if(change(s=>{const i=s.transactions.findIndex(x=>x.id===t.id);if(i>=0)s.transactions[i]=t;else s.transactions.push(t);},`${money(t.amount)} ${t.category} ${f.dataset.id?'updated':'saved'}.`)){f.dataset.saved='true';closeModal();render();}}
  else if(f.id==='forecast-form'){const opening=pennies(f.opening.value),buffer=pennies(f.buffer.value);if(!validDate(f.openingDate.value))throw new Error('Enter a valid opening balance date.');if(f.nextIncome.value&&(!validDate(f.nextIncome.value)||f.nextIncome.value<=today()))throw new Error('Next payment date must be after today.');if(persist({...state,opening,openingDate:f.openingDate.value,buffer,nextIncome:f.nextIncome.value,dirty:false,forecastReviewed:today()},'Forecast refreshed with your latest inputs.'))render();}
  else if(f.id==='event-form'){const amount=pennies(f.amount.value);if(!amount)throw new Error('Enter an amount greater than £0.00.');if(f.date.value&&!validDate(f.date.value))throw new Error('Enter a valid date.');const old=state.events.find(x=>x.id===f.dataset.id);if(old?.paid)throw new Error('This item has been recorded as paid or received. Correct the resulting transaction from your activity.');const row={id:f.dataset.id||uid(),name:f.name.value.trim(),type:f.type.value,amount,date:f.date.value,estimated:f.estimated.checked,paid:false};if(!row.name)throw new Error('Add a name for this item.');if(change(s=>{const i=s.events.findIndex(x=>x.id===row.id);if(i>=0)s.events[i]=row;else s.events.push(row);},'Timeline item saved. Refresh your forecast to use the new inputs.')){closeModal();render();}}
  else if(f.id==='budgets-form'){const budgets={};for(const c of categories){budgets[c]=pennies(f.elements.namedItem(c).value);if(budgets[c]<1||budgets[c]>1000000)throw new Error(`${c}: enter a limit between £0.01 and £10,000.00.`);}if(change(s=>{s.budgets=budgets;if(s.futureBudgets?.[weekStart()])s.futureBudgets[weekStart()]=budgets;},'Weekly limits saved.',false)){closeModal();render();}}
  else if(f.id==='allocation-form'){const payment=pennies(f.payment.value),reserve=pennies(f.reserve.value),weeks=Number(f.weeks.value),amounts=allocate(payment-reserve,weeks);if(payment<reserve)throw new Error(`${money(reserve-payment)} shortfall. Essentials stay protected; no negative allocation was saved.`);change(s=>{s.allocation={payment,reserve,weeks,amounts,startDate:weekStart()};s.futureBudgets={};s.resetUndo=null;},'Weekly allocation saved. Your transactions are unchanged.',false);}
  else if(f.id==='rehearsal-form'){const amount=pennies(f.amount.value);if(!amount)throw new Error('Enter a purchase amount greater than £0.00.');rehearsal={amount,name:f.name.value,value:f.amount.value};f.querySelector('.error').hidden=true;showRehearsal();}
  else if(f.id==='shared-form'){const people=[...f.querySelectorAll('[name="people"]:checked')].map(x=>x.value),amount=pennies(f.amount.value);if(!amount)throw new Error('Enter a bill amount greater than £0.00.');if(!validDate(f.date.value))throw new Error('Choose a valid due date.');const shares=splitBill(amount,people,f.method.value,people.map(p=>f.elements.namedItem('share-'+p)?.value||'0'));if(change(s=>s.shared.push({id:uid(),name:f.name.value.trim(),date:f.date.value,amount,people,shares,method:f.method.value,settled:[]}),'Shared bill saved.',false)){closeModal();render();}}
  else if(f.id==='csv-map-form'){const mapping=Object.fromEntries(['date','description','amount','category'].map(k=>[k,Number(f.elements.namedItem(k).value)]));if(new Set(Object.values(mapping)).size<4)throw new Error('Choose a different CSV column for each field.');csvMapping=mapping;csvPreview=previewCSV(csv,mapping,state.transactions);render();}
  else if(f.id==='reset-form'){
   const selected=[...f.querySelectorAll('[name="category"]:checked')].map(el=>el.value);
   const proposal=planReset(state,{amount:pennies(f.amount.value),selected});
   resetPreview={...proposal,signature:JSON.stringify(state)};
   f.querySelector('.error').hidden=true;document.querySelector('#reset-result').innerHTML=resetResultHTML();
  }
  else if(f.id==='settings-form'){change(s=>s.name=f.name.value.trim()||'you','Your details were saved.',false);}
}catch(err){error(f,err);}});
document.addEventListener('input',e=>{if(e.target.closest('#transaction-form'))transactionAfter();if(e.target.closest('#allocation-form'))allocationPreview();if(e.target.id==='transaction-search')filterTransactions();});
function filterTransactions(){const search=document.querySelector('#transaction-search').value.toLowerCase(),category=document.querySelector('#transaction-filter').value;document.querySelector('#transaction-list').innerHTML=transactionTable(state.transactions.filter(t=>(!category||t.category===category)&&(t.description+' '+t.category).toLowerCase().includes(search)));}
document.addEventListener('change',async e=>{if(e.target.id==='transaction-filter')filterTransactions();if(e.target.closest('#shared-form'))shareInputs();if(e.target.id==='csv-file'){const file=e.target.files[0];if(!file)return;try{if(!file.name.toLowerCase().endsWith('.csv'))throw new Error('Choose a .csv file with date, description, amount and category columns.');if(file.size>2*1024*1024)throw new Error('Choose a CSV file smaller than 2 MB.');const parsed=parseCSV(await file.text());csv=parsed;csvName=file.name;csvImported=0;csvMapping=null;csvPreview=null;render();}catch(err){toast(err.message);e.target.value='';}}});
document.addEventListener('click',e=>{const el=e.target.closest('button,a');if(!el)return;if(el.dataset.route){closeModal();location.hash=el.dataset.route;return;}if(el.dataset.editTransaction){transactionModal(el.dataset.editTransaction);return;}if(el.dataset.editEvent){eventModal(el.dataset.editEvent);return;}if(el.dataset.type){const form=el.closest('form');form.type.value=el.dataset.type;form.querySelectorAll('[data-type]').forEach(b=>b.classList.toggle('active',b===el));transactionAfter();return;}
 if(el.dataset.deleteTransaction){const id=el.dataset.deleteTransaction;confirmAction('Delete this transaction?','This removes the entry and recalculates your balance.','delete-transaction:'+id,'Delete transaction');return;}
 if(el.dataset.deleteEvent){confirmAction('Delete this timeline item?','The item will be removed. Any recorded payment remains in your transaction history.','delete-event:'+el.dataset.deleteEvent,'Delete item');return;}
 if(el.dataset.payEvent){const event=state.events.find(x=>x.id===el.dataset.payEvent);if(!event||event.paid)return;const t={id:uid(),date:today(),description:event.name,amount:event.amount,category:event.type==='income'?'Other':event.name.toLowerCase().includes('travel')?'Transport':'Other',type:event.type==='income'?'income':'expense'};if(change(s=>{s.events.find(x=>x.id===event.id).paid=true;s.transactions.push(t);},event.type==='income'?'Income received and added to your balance.':'Bill paid and expense recorded.')){closeModal();render();}return;}
 if(el.dataset.manageShared){const bill=state.shared.find(b=>b.id===el.dataset.manageShared);modal('Manage household shares',`<p class="dialog-copy">${esc(bill.name)} · ${money(bill.amount)} total. Marking a share settled does not change your personal balance.</p>${bill.people.map((p,i)=>`<div class="coverage-row"><span>${esc(p)} · ${money(bill.shares[i])}</span>${textButton(bill.settled.includes(p)?'Mark outstanding':'Mark settled',`data-settle-bill="${bill.id}" data-person="${esc(p)}"`,'check')}</div>`).join('')}<div class="spacer"></div>${textButton('Delete bill',`data-remove-shared="${bill.id}"`,'trash')}`);return;}
 if(el.dataset.settleBill){change(s=>{const b=s.shared.find(b=>b.id===el.dataset.settleBill),p=el.dataset.person;b.settled=b.settled.includes(p)?b.settled.filter(x=>x!==p):[...b.settled,p];},'Share status updated.',false);closeModal();render();return;}
 if(el.dataset.removeShared){confirmAction('Delete shared bill?','This removes the household bill and its settlement records.','delete-shared:'+el.dataset.removeShared,'Delete bill');return;}
 const action=el.dataset.action;if(!action)return;
 if(action==='close-dialog')closeModal();
 else if(action==='add-transaction')transactionModal();
 else if(action==='add-event')eventModal();
 else if(action==='budgets')budgetsModal();
 else if(action==='add-shared'){if(cloud.user)onlineBillModal();else{sharedModal();shareInputs();}}
 else if(action==='discard-reset'){resetPreview=null;render();toast('Proposal discarded. No saved data changed.');}
 else if(action==='apply-reset'){
   if(!resetPreview)return;
   if(resetPreview.signature!==JSON.stringify(state)){resetPreview=null;render();toast('Your inputs changed. Preview a fresh recovery plan first.');return;}
   if(change(s=>{s.resetUndo={allocation:structuredClone(s.allocation),futureBudgets:structuredClone(s.futureBudgets||{})};s.allocation=resetPreview.allocation;s.futureBudgets=resetPreview.futureBudgets;},'Future weeks adjusted. Essentials and past spending are unchanged.',false)){resetPreview=null;render();}
 }
 else if(action==='undo-reset'){
   if(!state.resetUndo)return;
   if(change(s=>{s.allocation=s.resetUndo.allocation;s.futureBudgets=s.resetUndo.futureBudgets;s.resetUndo=null;},'The last reset was undone. Recorded transactions are unchanged.',false)){resetPreview=null;render();}
 }
 else if(action==='export')exportCSV();
 else if(action==='coverage')coverage();
 else if(action==='discard-preview'){rehearsal=null;render();toast('Preview discarded. No transaction was added.');}
 else if(action==='clear-csv'){csv=null;csvPreview=null;csvMapping=null;csvImported=0;render();}
 else if(action==='confirm-csv'){
   if(!csv||!csvMapping)return;
   const result=prepareCSVImport(csv,csvMapping,state.transactions);
   if(!result.transactions.length){toast('There are no new valid rows to import.');return;}
   modal('Confirm CSV import',`<p class="dialog-copy">Add <strong>${result.transactions.length} expenses</strong> from ${esc(csvName)}? Your balance will decrease by ${money(result.transactions.reduce((sum,t)=>sum+t.amount,0))}. ${result.duplicates} duplicates and ${result.errors} invalid rows will be excluded.</p><div class="actions">${button('Keep reviewing','data-action="close-dialog"','secondary')}${button('Confirm import','data-action="import-csv"','','check')}</div>`);
 }
 else if(action==='import-csv'){
   if(!csv||!csvMapping)return;
   const result=prepareCSVImport(csv,csvMapping,state.transactions);
   if(!result.transactions.length){closeModal();toast('No new rows to import. Your saved records are unchanged.');return;}
   if(change(s=>s.transactions.push(...result.transactions),`${result.transactions.length} transactions imported.`)){
     csvImported=result.transactions.length;csvPreview=previewCSV(csv,csvMapping,state.transactions);closeModal();render();
   }
 }
 else if(action==='back-mapping'){csvPreview=null;render();}
 else if(action==='more')modal('More ways to plan',`<div class="stack">${routes.filter(r=>['allocation','rehearsal','import','reset','account','support'].includes(r[0])).map(([id,label,ico])=>button(label,`data-route="${id}"`,'full secondary',ico)).join('')}${button('Settings & data','data-route="settings"','full secondary','settings')}</div>`);
 else if(action==='start-blank')confirmAction('Start your own plan?','This clears the sample records and replaces your current data with an empty plan. Export your transactions first if you want to keep them.','confirm-blank','Start blank');
 else if(action==='delete-data')confirmAction('Delete all local data?','This permanently deletes your Termwise records from this browser. Download your export first if you need a copy.','confirm-delete','Delete all data');
 else if(action==='confirm-blank'||action==='confirm-delete'){const next=seed();next.opening=0;next.transactions=[];next.events=[];next.shared=[];next.nextIncome='';next.dirty=true;next.name=state.name;next.allocation={payment:0,reserve:0,weeks:6,amounts:allocate(0,6)};if(persist(next,'Local records cleared. Add your opening balance to begin.')){closeModal();location.hash='plan';render();}}
 else if(action.startsWith('delete-transaction:')){if(change(s=>s.transactions=s.transactions.filter(t=>t.id!==action.split(':')[1]),'Transaction deleted.')){closeModal();render();}}
 else if(action.startsWith('delete-event:')){if(change(s=>s.events=s.events.filter(t=>t.id!==action.split(':')[1]),'Timeline item deleted.')){closeModal();render();}}
 else if(action.startsWith('delete-shared:')){if(change(s=>s.shared=s.shared.filter(t=>t.id!==action.split(':')[1]),'Shared bill deleted.',false)){closeModal();render();}}
});
document.querySelector('#dialog').addEventListener('click',e=>{if(e.target===e.currentTarget){const r=e.currentTarget.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal();}});
window.addEventListener('hashchange',()=>{render();window.scrollTo(0,0);document.querySelector('#main').focus({preventScroll:true});});
window.addEventListener('resize',renderNav);
let householdLoaded=false,householdLoading=false,householdError='',groups=[],members=[],onlineBills=[],selectedGroup='';
 let snapshotsLoaded=false,snapshotsLoading=false,snapshotError='',snapshots=[],snapshotPreview=null,snapshotRequest=0;
function blankPlan(){const s=seed();return {...s,opening:0,transactions:[],events:[],shared:[],nextIncome:'',dirty:true,name:cloud.user?.user_metadata?.display_name||'you',allocation:{payment:0,reserve:0,weeks:6,startDate:weekStart(),amounts:allocate(0,6)},futureBudgets:{},resetUndo:null};}
function updateSyncStatus(){
 const labels={local:'Saved on this device',signedout:'Local mode · sign in to sync',loading:'Opening cloud account',pending:'Changes waiting to sync',saving:'Saving to cloud',synced:'Cloud up to date',error:'Saved locally · sync failed',conflict:'Cloud conflict · review account'};
 const label=document.querySelector('.local-label');if(label)label.innerHTML='<span></span>'+esc(labels[cloud.status]||'Local mode');
 document.querySelectorAll('[data-sync-status]').forEach(el=>el.textContent=labels[cloud.status]||'Local mode');
 if(!accountLoading&&cloud.user&&cloud.status==='synced'&&!cloud.pending){localStorage.removeItem(KEY+'-pending');localStorage.removeItem(KEY+'-base');}
}
async function bootstrapCloud(){
 cloud.addEventListener('status',updateSyncStatus);
 cloud.addEventListener('session',()=>openCloudAccount());
 cloud.addEventListener('recovery',()=>{authMode='recover';location.hash='account';render();});
 try{await cloud.init();if(cloud.user)await openCloudAccount();else{accountLoading=false;render();}}
 catch(e){accountLoading=false;accountIssue=e.message;cloud.status='error';render();toast('Cloud setup needs attention. Open Account & sync for details.');}
}
async function openCloudAccount(){
 const previousKey=KEY;accountLoading=true;accountIssue='';householdLoaded=false;householdLoading=false;snapshotsLoaded=false;snapshotsLoading=false;groups=[];members=[];onlineBills=[];snapshots=[];snapshotPreview=null;selectedGroup='';csv=null;csvMapping=null;csvPreview=null;csvName='';csvImported=0;resetPreview=null;rehearsal=null;snapshotRequest++;
 if(!cloud.user){
   KEY=GUEST_KEY;try{state=JSON.parse(localStorage.getItem(KEY))||seed();if(previousKey!==GUEST_KEY&&localStorage.getItem(previousKey+'-pending')!=='true'){localStorage.removeItem(previousKey);localStorage.removeItem(previousKey+'-base');}}catch{state=seed();}
   cloud.status=cloud.configured?'signedout':'local';accountLoading=false;render();return;
 }
 const userId=cloud.user.id;KEY=GUEST_KEY+':'+userId;render();
 try{
   const cached=JSON.parse(localStorage.getItem(KEY)||'null'),hadPending=localStorage.getItem(KEY+'-pending')==='true',base=Number(localStorage.getItem(KEY+'-base'));
   const remote=await cloud.load();if(cloud.user?.id!==userId)return;
   const fresh={...blankPlan(),...(remote||{})};
   if(!Array.isArray(fresh.transactions)||!Array.isArray(fresh.events)||!fresh.budgets)throw new Error('Cloud budget format is invalid. Export your local copy before resetting it.');
   if(hadPending&&cached&&JSON.stringify(cached)!==JSON.stringify(remote)){
     state=cached;
     if(base!==cloud.revision){cloud.blocked=true;cloud.status='conflict';cloud.error='Your local copy and the cloud both changed. Export your local transactions, then reload the cloud copy.';}
     else cloud.queue(state);
   }else{state=fresh;localStorage.setItem(KEY,JSON.stringify(state));if(!remote)cloud.queue(state);}
 }catch(e){try{state=JSON.parse(localStorage.getItem(KEY))||blankPlan();}catch{state=blankPlan();}accountIssue=e.message;cloud.blocked=true;cloud.status='error';}
 accountLoading=false;render();if(accountIssue)toast(accountIssue);
}
function cloudButton(label,action,kind='secondary',ico='arrow'){return button(label,`data-cloud-action="${action}"`,kind,ico);}
function accountPage(){
 if(!cloud.configured)return heading('Your plan, across devices.','Connect a backend to enable accounts and secure sharing.','','ACCOUNT & SYNC')+panel('Supabase setup required',note('Local features are available now.','CSV import and Reset Week already work. Accounts, cloud sync and online sharing become available when the project is configured.','lime','check')+'<div class="spacer"></div><p class="small-copy">Follow the Supabase setup guide in the repository. Create the database tables, then add SUPABASE_URL and SUPABASE_PUBLISHABLE_KEY in your hosting environment and redeploy. Never use a service-role key in the browser.</p>');
 if(!cloud.user)return heading('Your own space for your money.','Sign in to save your plan across devices.','','ACCOUNT & SYNC')+`<div class="grid-main">${panel(authMode==='signup'?'Create an account':'Welcome back',`<form id="cloud-auth-form"><div class="error" role="alert" hidden></div>${authMode==='signup'?field('Your name','displayName','','text','maxlength="60" required autocomplete="name"'):''}${field('Email','email','','email','required autocomplete="email"')}${field('Password','password','','password',`required minlength="8" autocomplete="${authMode==='signup'?'new-password':'current-password'}"`)}${button(authMode==='signup'?'Create account':'Sign in','type="submit"','full','shield')}</form><div class="actions">${cloudButton(authMode==='signup'?'Already registered? Sign in':'Create an account','toggle-auth')}${cloudButton('Reset password','reset-password')}</div>${accountIssue?note('Connection error',esc(accountIssue),'amber'):''}`)}<div class="stack">${note('Your local plan stays separate.','Signing in opens your cloud account. You can choose to copy your device plan afterward; it is never uploaded automatically.','','shield')}${sessionStorage.getItem('termwise-invite')?note('An invitation is waiting.','Sign in with the invited email to review and accept it.','lime','shared'):''}${sessionStorage.getItem('termwise-snapshot')?note('A support summary is waiting.','Sign in with the recipient email to view it.','','shield'):''}</div></div>`;
 return heading('Your account. Your control.',esc(cloud.user.email),'','ACCOUNT & SYNC')+`<div class="grid-main"><div class="stack">${panel('Cloud storage',`<p class="small-copy" data-sync-status></p>${cloud.error||accountIssue?note('Action needed',esc(cloud.error||accountIssue),'amber'):''}<div class="actions">${cloudButton('Sync now','sync-now','','check')}${cloudButton('Reload cloud copy','reload-cloud')}</div><p class="form-note">Sync uses version checks. Changes on another device cannot silently overwrite this plan.</p>`)}${panel('Bring your local plan',`<p class="small-copy">Copy this browser’s guest plan into your signed-in account. This replaces your current cloud plan only after confirmation.</p><div class="spacer"></div>${cloudButton('Copy device plan to account','copy-guest')}`)}${sessionStorage.getItem('termwise-invite')?panel('Accept household invitation',`<form id="accept-invite-form"><div class="error" hidden role="alert"></div>${field('Your household display name','displayName',state.name==='you'?'':state.name,'text','required maxlength="60"')}${button('Accept invitation','type="submit"','full','shared')}</form>`):''}${cloud.recovery?panel('Choose a new password',`<form id="new-password-form"><div class="error" hidden role="alert"></div>${field('New password','password','','password','required minlength="8" autocomplete="new-password"')}${button('Save new password','type="submit"','full','shield')}</form>`):''}${cloudButton('Sign out','signout')}</div><div class="stack">${note('Personal records stay private.','Only your account can read your cloud budget. Household collaboration exposes only records you explicitly add to that household.','lime','shield')}${cloudButton('Household collaboration','open-shared')}${cloudButton('Support snapshots','open-support')}${sessionStorage.getItem('termwise-snapshot')?cloudButton('View received summary','open-support'):''}</div></div>`;
}
async function refreshHouseholds(){
 if(!cloud.user||householdLoading)return;const userId=cloud.user.id;householdLoading=true;householdError='';
 try{const nextGroups=await cloud.households(),nextSelected=nextGroups.some(g=>g.id===selectedGroup)?selectedGroup:nextGroups[0]?.id||'',result=nextSelected?await Promise.all([cloud.members(nextSelected),cloud.bills(nextSelected)]):[[],[]];if(cloud.user?.id!==userId)return;groups=nextGroups;selectedGroup=nextSelected;[members,onlineBills]=result;householdLoaded=true;}
 catch(e){if(cloud.user?.id===userId){householdError=e.message;householdLoaded=true;}}
 finally{if(cloud.user?.id===userId){householdLoading=false;if(route==='shared')render();}}
}
function onlineShared(){
 const group=groups.find(g=>g.id===selectedGroup),own=cloud.user.id;
 return heading('Your household, on the same page.','Only household members can see these shared bills.',cloudButton('Refresh','refresh-household'),'HOUSEHOLD COLLABORATION')+`<div class="grid-main"><div class="stack">${householdError?note('Could not load household',esc(householdError),'amber'):''}${householdLoading?empty('Loading your household…'):''}${groups.length?`<label class="field"><span>Household</span><select id="online-household">${groups.map(g=>`<option value="${g.id}" ${g.id===selectedGroup?'selected':''}>${esc(g.name)}</option>`).join('')}</select></label>`:''}${onlineBills.map(b=>`<article class="bill-card" style="background:white"><div class="bill-top"><div><h3>${esc(b.name)}</h3><p>${money(Number(b.amount))} total · ${esc(b.method)} · ${dateLabel(b.due_date)}</p></div><div><strong>${money(Number(b.shares[own]||0))}</strong><p>Your share</p></div></div><div class="bill-shares">${Object.entries(b.shares).map(([id,value])=>`<div>${esc(members.find(m=>m.user_id===id)?.display_name||'Former member')}<strong>${money(Number(value))}</strong>${status(b.settled_ids.includes(id)?'Settled':'Outstanding',b.settled_ids.includes(id)?'':'amber')}</div>`).join('')}</div><div class="bill-actions">${Object.hasOwn(b.shares,own)?cloudButton(b.settled_ids.includes(own)?'Mark my share unpaid':'Settle my share',`settle:${b.id}`):''}${b.created_by===own||group?.owner_id===own?cloudButton('Delete bill',`delete-online-bill:${b.id}`,'danger','trash'):''}</div></article>`).join('')}${!onlineBills.length&&!householdLoading?empty(group?'No shared bills yet. Record your first household cost.':'Create a household to collaborate.'):''}${group?cloudButton('Record a shared bill','add-online-bill','','plus'):''}</div><div class="stack">${panel('Household members',members.map(m=>`<div class="coverage-row"><span>${esc(m.display_name)}</span>${status(m.user_id===own?'You':'Member')}</div>`).join('')||'<p class="small-copy">No household selected.</p>')}${group?.owner_id===own?cloudButton('Invite a housemate','invite-housemate'):''}${cloudButton('Create household','create-household')}${note('Private spending stays private.','Members can read this ledger and settle their own shares. Your transaction history is never part of the household response.','lime','shield')}</div></div>`;
}
function onlineBillModal(){
 if(!selectedGroup){toast('Create or select a household first.');return;}
 modal('Record a household bill',`<form id="online-bill-form"><div class="error" hidden role="alert"></div>${field('Bill name','name','','text','required maxlength="100"')}${field('Amount (£)','amount','','number','required step="0.01" min="0.01"')}${field('Due date','date',today(),'date','required')}<span class="field-label">Participants</span>${members.map(m=>`<label class="check"><input type="checkbox" name="participant" value="${m.user_id}" checked>${esc(m.display_name)}</label>`).join('')}<label class="field"><span>Split method</span><select name="method"><option value="equal">Equal</option><option value="percentage">Percentage</option><option value="custom">Custom amounts</option></select></label><div id="online-share-inputs"></div>${button('Save household bill','type="submit"','full','check')}</form>`);onlineShareInputs();
}
function onlineShareInputs(){const f=document.querySelector('#online-bill-form');if(!f)return;const people=[...f.querySelectorAll('[name="participant"]:checked')].map(el=>el.value);document.querySelector('#online-share-inputs').innerHTML=f.method.value==='equal'?note('Split equally.','All selected members receive reconciled shares.'):people.map(id=>field(esc(members.find(m=>m.user_id===id)?.display_name)+(f.method.value==='percentage'?' (%)':' (£)'),'share-'+id,'','number','required min="0" step="0.01"')).join('');}
async function refreshSnapshots(){
 if(!cloud.user||snapshotsLoading)return;const userId=cloud.user.id;snapshotsLoading=true;snapshotError='';
 try{const result=await cloud.snapshots();if(cloud.user?.id!==userId)return;snapshots=result;snapshotsLoaded=true;}catch(e){if(cloud.user?.id===userId){snapshotError=e.message;snapshotsLoaded=true;}}
 finally{if(cloud.user?.id===userId){snapshotsLoading=false;if(route==='support')render();}}
}
function summaryHTML(summary){return `<p class="small-copy">${dateLabel(summary.from)} to ${dateLabel(summary.to)}</p>${Object.entries(summary.totals||{}).map(([c,n])=>`<div class="coverage-row"><span>${esc(c)}</span><strong>${money(Number(n))}</strong></div>`).join('')}`;}
function supportPage(){
 if(!cloud.user)return heading('Share a little. Keep control.','Sign in to share a selected summary with a named recipient.','','SUPPORT SNAPSHOTS')+panel('Private by default',note('Account connection required.','Recipients must sign in with the email you choose. Expiry and revocation are enforced by the database.','','shield')+'<div class="spacer"></div>'+button('Open account settings','data-route="account"','full'));
 const requested=sessionStorage.getItem('termwise-snapshot');
 const cards=snapshots.filter(s=>!requested||s.id===requested);
 return heading('Support, on your terms.','Choose exactly what to share, with whom, and for how long.',cloudButton('Refresh','refresh-snapshots'),'CONSENT-BASED SUPPORT SNAPSHOTS')+`<div class="grid-main"><div class="stack">${panel('Prepare a summary',`<form id="snapshot-form"><div class="error" hidden role="alert"></div>${field('Recipient email','recipient','','email','required')}${field('From','from',weekStart(),'date','required')}${field('To','to',today(),'date','required')}${field('Access period in days','days','7','number','required min="1" max="30" step="1"')}<span class="field-label">Categories to include</span>${categories.map(c=>`<label class="check"><input type="checkbox" name="category" value="${esc(c)}" checked>${esc(c)}</label>`).join('')}${button('Preview selected summary','type="submit"','full')}<div id="snapshot-preview"></div></form>`)}${note('Revocation stops future access.','A recipient may already have seen or copied a summary. Shared snapshots are dated copies, not live feeds. Transaction descriptions and notes are never included.','','shield')}</div><div class="stack">${snapshotError?note('Could not load summaries',esc(snapshotError),'amber'):''}${snapshotsLoading?empty('Loading summaries…'):''}${requested?cloudButton('Show all summaries','all-snapshots'):''}${cards.map(s=>{const owner=s.owner_id===cloud.user.id;return panel(owner?'Summary you shared':'Summary shared with you',`<p class="small-copy">${owner?'Recipient: '+esc(s.recipient_email):'Read-only category totals'}<br>Created ${esc(new Date(s.created_at).toLocaleString())}<br>Expires ${esc(new Date(s.expires_at).toLocaleString())}</p><div class="spacer"></div>${summaryHTML(s.summary)}<div class="spacer"></div>${status(s.revoked_at?'Revoked':new Date(s.expires_at)<=new Date()?'Expired':'Active',s.revoked_at?'amber':'')}${owner?`<div class="actions">${!s.revoked_at&&new Date(s.expires_at)>new Date()?cloudButton('Revoke access',`revoke-snapshot:${s.id}`,'danger','shield'):''}${cloudButton('Copy recipient link',`copy-snapshot:${s.id}`)}</div>`:''}`);}).join('')}${!cards.length&&!snapshotsLoading?empty(requested?'This summary is unavailable, expired, revoked, or intended for another email.':'No accessible snapshots yet.'):''}</div></div>`;
}
function snapshotPreviewHTML(){if(!snapshotPreview)return '';return '<div class="spacer"></div>'+panel('Exactly what will be shared',`<p class="small-copy">Recipient: <strong>${esc(snapshotPreview.recipient)}</strong><br>Access for ${snapshotPreview.days} days after confirmation.</p><div class="spacer"></div>${summaryHTML(snapshotPreview.summary)}<div class="spacer"></div><label class="check"><input type="checkbox" id="snapshot-consent">I agree to share these totals with this recipient.</label>${cloudButton('Confirm sharing','confirm-snapshot','','shield')}`);}
const cloudForms=new Set(['cloud-auth-form','new-password-form','accept-invite-form','online-bill-form','create-household-form','invite-housemate-form','snapshot-form','password-reset-form']);
document.addEventListener('submit',async e=>{
 const f=e.target;if(!cloudForms.has(f.id))return;e.preventDefault();const submit=f.querySelector('[type="submit"]');if(submit?.disabled)return;if(submit)submit.disabled=true;
 try{
  if(f.id==='cloud-auth-form'){if(authMode==='signup'){const active=await cloud.signUp(f.email.value,f.password.value,f.displayName.value.trim());toast(active?'Account created. Opening your cloud plan…':'Check your email to confirm your account, then sign in.');}else await cloud.signIn(f.email.value,f.password.value);}
  else if(f.id==='new-password-form'){await cloud.updatePassword(f.password.value);toast('Password updated.');render();}
  else if(f.id==='password-reset-form'){await cloud.resetPassword(f.email.value);closeModal();toast('If the account exists, a password reset email will arrive.');}
  else if(f.id==='create-household-form'){selectedGroup=await cloud.rpc('create_household',{p_name:f.name.value.trim(),p_display_name:f.displayName.value.trim()});closeModal();await refreshHouseholds();toast('Household created.');}
  else if(f.id==='invite-housemate-form'){const invite=await cloud.rpc('invite_housemate',{p_household:selectedGroup,p_email:f.email.value.trim()});modal('Invitation ready',note('Only the invited email can accept.','The link expires in seven days. Copy it and share it with your housemate.','','shield')+'<div class="spacer"></div>'+field('Invitation link','link',location.origin+'/#invite='+invite,'text','readonly'));}
  else if(f.id==='accept-invite-form'){selectedGroup=await cloud.rpc('accept_household_invite',{p_invite:sessionStorage.getItem('termwise-invite'),p_display_name:f.displayName.value.trim()});sessionStorage.removeItem('termwise-invite');householdLoaded=false;location.hash='shared';render();toast('Household invitation accepted.');}
  else if(f.id==='online-bill-form'){const ids=[...f.querySelectorAll('[name="participant"]:checked')].map(el=>el.value),amount=pennies(f.amount.value),shares=splitBill(amount,ids,f.method.value,ids.map(id=>f.elements.namedItem('share-'+id)?.value||'0'));await cloud.rpc('create_household_bill',{p_household:selectedGroup,p_name:f.name.value.trim(),p_amount:amount,p_due_date:f.date.value,p_method:f.method.value,p_shares:Object.fromEntries(ids.map((id,i)=>[id,shares[i]]))});closeModal();await refreshHouseholds();toast('Household bill saved.');}
  else if(f.id==='snapshot-form'){
    const request=++snapshotRequest,selected=[...f.querySelectorAll('[name="category"]:checked')].map(el=>el.value),from=f.from.value,to=f.to.value,recipient=f.recipient.value.trim(),days=Number(f.days.value);
    if(!selected.length)throw new Error('Choose at least one category.');if(from>to)throw new Error('The end date must be on or after the start date.');
    await cloud.flush();const preview=await cloud.rpc('preview_support_snapshot',{p_categories:selected,p_from:from,p_to:to});
    if(request!==snapshotRequest||!f.isConnected)throw new Error('The scope changed. Preview the selected summary again.');
    snapshotPreview={...preview,selected,from,to,recipient,days};document.querySelector('#snapshot-preview').innerHTML=snapshotPreviewHTML();
  }
  const el=f.querySelector('.error');if(el)el.hidden=true;
 }catch(err){error(f,err);}finally{if(submit)submit.disabled=false;}
});
document.addEventListener('input',e=>{if(e.target.closest('#reset-form')){resetPreview=null;document.querySelector('#reset-result').innerHTML='';}if(e.target.closest('#snapshot-form')&&!e.target.closest('#snapshot-preview')){snapshotRequest++;snapshotPreview=null;document.querySelector('#snapshot-preview').innerHTML='';}});
document.addEventListener('change',e=>{if(e.target.closest('#online-bill-form'))onlineShareInputs();if(e.target.id==='online-household'){selectedGroup=e.target.value;refreshHouseholds();}});
document.addEventListener('click',async e=>{
 const el=e.target.closest('[data-cloud-action]');if(!el||el.disabled)return;const action=el.dataset.cloudAction;el.disabled=true;
 try{
  if(action==='toggle-auth'){authMode=authMode==='signup'?'signin':'signup';render();}
  else if(action==='reset-password')modal('Reset your password',`<form id="password-reset-form"><div class="error" hidden role="alert"></div>${field('Account email','email','','email','required')}${button('Send reset email','type="submit"','full')}</form>`);
  else if(action==='signout'){if(cloud.pending||cloud.blocked){modal('Sign out with unsynced changes?',`<p class="dialog-copy">Your unsynced account copy will stay in this browser for recovery when you sign in again. Export it first if you need a separate copy.</p><div class="actions">${button('Cancel','data-action="close-dialog"','secondary')}${cloudButton('Sign out now','signout-unsynced','danger')}</div>`);}else{await cloud.signOut();toast('Signed out. Your guest plan is separate.');}}
  else if(action==='signout-unsynced'){await cloud.signOut(true);closeModal();toast('Signed out. Unsynced changes remain on this device.');}
  else if(action==='sync-now'){if(cloud.status!=='conflict')cloud.blocked=false;if(!cloud.pending)cloud.queue(state);await cloud.flush();toast('Cloud plan saved.');}
  else if(action==='reload-cloud')modal('Reload the cloud copy?',`<p class="dialog-copy">Unsynced local changes will be replaced. Export your transactions first if you need a copy.</p><div class="actions">${button('Cancel','data-action="close-dialog"','secondary')}${cloudButton('Replace local copy','confirm-reload','danger')}</div>`);
  else if(action==='confirm-reload'){localStorage.removeItem(KEY+'-pending');localStorage.removeItem(KEY+'-base');cloud.pending=null;closeModal();await openCloudAccount();}
  else if(action==='copy-guest')modal('Copy your device plan?',`<p class="dialog-copy">This replaces your signed-in budget with this browser’s guest records. Existing support snapshots remain dated copies; household bills are unaffected.</p><div class="actions">${button('Cancel','data-action="close-dialog"','secondary')}${cloudButton('Replace account plan','confirm-copy-guest','danger')}</div>`);
  else if(action==='confirm-copy-guest'){const guest=JSON.parse(localStorage.getItem(GUEST_KEY)||'null');if(!guest)throw new Error('No saved guest plan exists on this browser.');if(persist(guest,'Device plan copied.')){closeModal();render();await cloud.flush();}}
  else if(action==='open-shared')location.hash='shared';
  else if(action==='open-support')location.hash='support';
  else if(action==='refresh-household')await refreshHouseholds();
  else if(action==='create-household')modal('Create a household',`<form id="create-household-form"><div class="error" hidden role="alert"></div>${field('Household name','name','','text','required maxlength="100"')}${field('Your display name','displayName',state.name==='you'?'':state.name,'text','required maxlength="60"')}${button('Create household','type="submit"','full','shared')}</form>`);
  else if(action==='invite-housemate')modal('Invite a housemate',`<form id="invite-housemate-form"><div class="error" hidden role="alert"></div>${field('Housemate email','email','','email','required')}${button('Create invitation link','type="submit"','full','shared')}<p class="form-note">Only a signed-in account with this email can accept. No email is sent automatically.</p></form>`);
  else if(action==='add-online-bill')onlineBillModal();
  else if(action.startsWith('settle:')){const bill=onlineBills.find(b=>b.id===action.slice(7));await cloud.rpc('settle_household_share',{p_bill:bill.id,p_settled:!bill.settled_ids.includes(cloud.user.id)});await refreshHouseholds();}
  else if(action.startsWith('delete-online-bill:')){modal('Delete household bill?',`<p class="dialog-copy">Only unsettled bills can be deleted. Settled records remain as payment history.</p><div class="actions">${button('Cancel','data-action="close-dialog"','secondary')}${cloudButton('Delete bill','confirm-delete-online:'+action.slice(19),'danger','trash')}</div>`);}
  else if(action.startsWith('confirm-delete-online:')){await cloud.rpc('delete_household_bill',{p_bill:action.slice(22)});closeModal();await refreshHouseholds();}
  else if(action==='refresh-snapshots')await refreshSnapshots();
  else if(action==='all-snapshots'){sessionStorage.removeItem('termwise-snapshot');render();}
  else if(action==='confirm-snapshot'){
    if(!snapshotPreview||!document.querySelector('#snapshot-consent')?.checked)throw new Error('Review the preview and confirm consent before sharing.');
    const p=snapshotPreview;await cloud.flush();const id=await cloud.rpc('create_support_snapshot',{p_categories:p.selected,p_from:p.from,p_to:p.to,p_recipient:p.recipient,p_days:p.days,p_expected_revision:p.revision});snapshotPreview=null;snapshotsLoaded=false;await refreshSnapshots();toast('Summary shared. Only the selected email can open it.');
  }
  else if(action.startsWith('revoke-snapshot:')){await cloud.rpc('revoke_support_snapshot',{p_snapshot:action.slice(16)});await refreshSnapshots();toast('Access revoked. Future requests will be denied.');}
  else if(action.startsWith('copy-snapshot:')){const link=location.origin+'/#snapshot='+action.slice(14);try{await navigator.clipboard.writeText(link);toast('Recipient link copied.');}catch{modal('Recipient link',field('Link','link',link,'text','readonly'));}}
 }catch(err){toast(err.message);}finally{el.disabled=false;}
});
// Never cache recipient summaries. Refresh visible shared views and access checks regularly.
setInterval(()=>{if(document.hidden||!cloud.user)return;if(route==='support')refreshSnapshots();if(route==='shared')refreshHouseholds();},30000);

bootstrapCloud();render();if(storageError)toast('Browser storage could not be read. Showing sample data.');
